std::queue<Job> q; std::mutex m; std::condition_variable cv;

// producer, after the last item:
{ std::lock_guard lk(m); q.push(Job::stop()); }
cv.notify_one();

// consumer:
for (;;) {
    Job job;
    { std::unique_lock lk(m); cv.wait(lk, [&]{ return !q.empty(); }); job = std::move(q.front()); q.pop(); }
    if (job.is_stop()) break;        // drain finished
    process(job);
}

