std::queue<Job> q; std::mutex m; std::condition_variable_any cv;

std::jthread worker([&](std::stop_token st) {
    std::unique_lock lk(m);
    while (cv.wait(lk, st, [&]{ return !q.empty(); })) {
        Job job = std::move(q.front()); q.pop();
        lk.unlock(); process(job); lk.lock();
    }
});
